// Regenerates supabase/migrations/0001_rc_schema.sql from the portable schema.
import { writeFileSync } from "node:fs";
import { SCHEMA } from "../src/lib/db/schema";

const tables = SCHEMA.map((s) => s.match(/CREATE TABLE IF NOT EXISTS (\w+)/)?.[1]).filter(Boolean) as string[];
const out = [
  "-- RC schema for Supabase / PostgreSQL. Generated by scripts/gen-migration.ts — do not edit by hand.",
  "-- RC's server connects with DATABASE_URL and enforces tenant isolation (org_id) in its data layer.",
  "-- Row Level Security is enabled with NO policies, so the public anon/authenticated API roles",
  "-- cannot read any of this data (athlete data concerns minors). Only the server connection can.",
  "",
  ...SCHEMA.map((s) => s.trim() + ";\n"),
  ...tables.map((t) => `ALTER TABLE ${t} ENABLE ROW LEVEL SECURITY;`),
  "",
].join("\n");
writeFileSync("supabase/migrations/0001_rc_schema.sql", out);
console.log(`Wrote ${tables.length} tables`);
